  'tool.readStateDesc': { 'zh-CN': '读取项目的全局状态信息，包括小说配置、近章要点等。用于了解项目的整体概况。', 'en-US': 'Read the project\'s global state: novel config, recent chapter notes, etc. For understanding the project overview.', 'ru-RU': 'Чтение глобального состояния проекта: конфигурация романа, заметки глав. Для общего обзора.' },
